scripts.张琳心对话.txt:
//同伴对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290;
	If ($Event == 300) @Event300;
	If ($Event == 310) @Event310;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;
	
	Return;
	
@Event280:
	If ($Talk280 == 0) @Talk0;	
	If ($Talk280 == 1) @Talk1;	
	Return;
@Talk0:	
	Say("独孤剑：琳儿，我先送你去长安找你哥吧。", 1);
	Say("张琳儿：我想先和你上华山，华山顾前辈的处境目前十分危险，我们应该尽快赶去通知他，稍后再去长安找我哥也不迟。", 21);
	Say("独孤剑：也好，那我们尽快赶去华山。", 1);
	Assign($Talk280, 1);
	Return;
@Talk1:	
	Say("独孤剑：这石塘镇因为临近长安，原本人烟十分密集，可如今由于金兵南侵，已经变得非常萧条了。", 1);
	Say("张琳儿：我看镇上的居民面容皆有愁色，唉！连年的战争只是苦了这些老百姓。", 21);
	Return;

@Event290:
	Say("张琳儿：我们问问镇上的居民吧，看看他们知不知道上华山的其他办法。", 21);
	Return;
	
@Event300:
	Say("张琳儿：我们快去长安。", 21);
	Return;		
	
@Event310:
	Say("张琳儿：我们快去找李三吧！", 21);
	Return;	
	
@Event320:
	Say("张琳儿：事不宜迟，我们赶快上山，再晚可能就来不及了。", 21);
	Return; 	
	
@Event320:
	Say("张琳儿：事不宜迟，我们赶快上山，再晚可能就来不及了。", 21);
	Return; 
	
@Event360:
	Say("张琳儿：怎么会有这样的巧合……顾枫之死必有蹊跷。", 21);
	Return;

