scripts.石塘镇居民3之何大叔对话.txt:
// 和何大叔的对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290;
	If ($Event == 300) @Event290;
	If ($Event == 310) @Event290;
	If ($Event == 360) @Event360;
	
	Return;

