	DelNpc("小雷");
	DelNpc("段芙蓉");
	SaveNpc();
	GetRandNum($Talkheshu280,0,1);
	If ($Talkheshu280 == 0) @Talk0;
	If ($Talkheshu280 == 1) @Talk1;	
@Talk0:	
	Say("何大叔：听说华山上顾枫和林海两个人为一个华山掌门要大打出手，真不知这些人是怎么想的，难道这个位子就这么好，值得兄弟俩自相残杀？", 0);
