scripts.石塘镇居民5之钟大爷对话.txt:
// 和钟大爷的对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290;
	If ($Event == 300) @Event300;
	
	Say("钟大爷：哎！王师北定中原日，家祭无忘告乃翁……", 0);
	Return;
	
	
@Event280:
	If ($Talkdaye280 == 0) @Talkdaye0;
	If ($Talkdaye280 == 1) @Talkdaye1;
@Talkdaye0:	
	DelNpc("小雷");
	DelNpc("段芙蓉");
	SaveNpc();
	Say("钟大爷：自古华山一条路，欲上云台神也愁。", 0);
	Say("独孤剑：老丈，去华山怎么走？", 1);
	Say("钟大爷：出了东边的路口，再往北走就到了，二位可是要上华山？", 0);
	Say("独孤剑：正是。", 1);
	Say("钟大爷：华山的路可不好走，二位可要当心哪。", 0);
	Assign($Talkdaye280, 1);
	Return;
@Talkdaye1:
	Say("钟大爷：华山的路可不好走，二位可要当心哪。", 0);
	Return;
	
	
@Event290:
	Say("张琳心：这位老丈，上华山还有其他路吗？", 21);
	Say("钟大爷：你有没有听说过“自古华山一条路”？很多地方是一夫当关，万夫莫开，天生险绝，插翅难飞啊。", 0);
	Say("独孤剑：偌大的一座山难道没有其它小道？", 1);
	Say("钟大爷：这个吗……这里有个樵夫叫李三，他经常上山打柴、采药，对华山很熟悉。你们可以去找他，也许会有其它路。不过不巧啊，今天他刚进城去了。", 0);
	Say("独孤剑：多谢老丈指点。", 2);
	SetMapTrap(1, "trap01.txt");	
	SetMapTrap(2, "trap02.txt");	
	Assign($Event, 300);
	Memo("在石塘镇了解到钟大爷李三对上华山的路很熟，但是李三去了长安，于是两人决定先到长安去找李三。");
	Return;

	
@Event300:
	Say("钟大爷：李三去了长安城，你们去城里找他吧。", 0);
	Return;

